//! Pure wire protocol for the ZyXEL Multiboot (zycast) flash protocol.
//!
//! Byte-identical port of the Go reference (`cmd/zycast`, itself from
//! openwrt/firmware-utils `zycast.c`): UDP multicast, a 30-byte header per
//! packet, 1024-byte payload chunks. The golden-vector tests pin this
//! implementation to the Go sender's exact bytes — the vectors were
//! generated by running the Go header builder on a deterministic buffer.

/// Big-endian `"zyx\0"` magic.
pub const MAGIC: u32 = 0x7A79_7800;
/// Header size in bytes.
pub const HEADER_LEN: usize = 30;
/// Payload bytes per packet.
pub const CHUNK_SIZE: usize = 1024;
/// Default multicast group.
pub const DEFAULT_GROUP: &str = "225.0.0.0";
/// Default multicast port.
pub const DEFAULT_PORT: u16 = 5631;
/// Default inter-packet delay (matches the Go sender).
pub const DEFAULT_DELAY_MS: u64 = 10;
/// Default loop count. Bounded on purpose: the bootloader listens on EVERY
/// boot, so an unlimited sender re-flashes the target forever — the
/// kill-the-sender-the-moment-the-flash-lands rule, enforced structurally.
pub const DEFAULT_LOOPS: u32 = 3;
/// Pause between send loops (matches the Go sender).
pub const LOOP_PAUSE_MS: u64 = 200;

/// Image-partition bitmask the bootloader acts on.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ImageType {
    /// Bootbase partition (rarely flashed; highest brick risk).
    Bootbase,
    /// ROM partition.
    Rom,
    /// RAS — the running firmware image (the normal case).
    Ras,
    /// ROMD partition.
    Romd,
    /// Backup partition.
    Backup,
}

impl ImageType {
    /// Wire bitmask value.
    pub fn bit(self) -> u8 {
        match self {
            ImageType::Bootbase => 0x01,
            ImageType::Rom => 0x02,
            ImageType::Ras => 0x04,
            ImageType::Romd => 0x08,
            ImageType::Backup => 0x10,
        }
    }
}

impl std::fmt::Display for ImageType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let s = match self {
            ImageType::Bootbase => "bootbase",
            ImageType::Rom => "rom",
            ImageType::Ras => "ras",
            ImageType::Romd => "romd",
            ImageType::Backup => "backup",
        };
        f.write_str(s)
    }
}

impl std::str::FromStr for ImageType {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "bootbase" => Ok(ImageType::Bootbase),
            "rom" => Ok(ImageType::Rom),
            "ras" => Ok(ImageType::Ras),
            "romd" => Ok(ImageType::Romd),
            "backup" => Ok(ImageType::Backup),
            other => Err(format!(
                "unknown image type {other:?} (want bootbase|rom|ras|romd|backup)"
            )),
        }
    }
}

/// 16-bit sum of all bytes, folded once. One fold suffices by construction:
/// the largest chunk (1024 bytes) sums to at most 1024·255 < 2¹⁸, which a
/// single fold + mask reduces below 2¹⁶ without re-carrying.
pub fn checksum(data: &[u8]) -> u16 {
    let total: u32 = data.iter().map(|&b| u32::from(b)).sum();
    ((total >> 16) + total) as u16
}

/// Number of chunks a file of `file_len` bytes splits into.
pub fn chunk_count(file_len: usize) -> u32 {
    file_len.div_ceil(CHUNK_SIZE) as u32
}

/// The chunk with zero-based index `pid`.
pub fn chunk_at(image: &[u8], pid: u32) -> &[u8] {
    let off = pid as usize * CHUNK_SIZE;
    let end = (off + CHUNK_SIZE).min(image.len());
    &image[off..end]
}

/// Build the 30-byte header for one chunk (layout per the Go reference).
pub fn header(chunk: &[u8], pid: u32, file_len: u32, ty: ImageType) -> [u8; HEADER_LEN] {
    let mut h = [0u8; HEADER_LEN];
    h[0..4].copy_from_slice(&MAGIC.to_be_bytes());
    h[4..6].copy_from_slice(&checksum(chunk).to_be_bytes());
    h[6..10].copy_from_slice(&pid.to_be_bytes());
    h[10..14].copy_from_slice(&(chunk.len() as u32).to_be_bytes());
    h[14..18].copy_from_slice(&file_len.to_be_bytes());
    h[18..20].copy_from_slice(&0u16.to_be_bytes());
    let bit = ty.bit();
    h[20] = bit;
    h[21] = bit;
    h[22] = b'F';
    h[23] = b'F';
    h[24] = 0x01;
    h
}

#[cfg(test)]
mod tests {
    use super::*;

    fn hex(bytes: &[u8]) -> String {
        bytes.iter().map(|b| format!("{b:02x}")).collect()
    }

    fn golden_buffer() -> Vec<u8> {
        (0..2148).map(|i| (i * 7 % 251) as u8).collect()
    }

    #[test]
    fn headers_are_byte_identical_to_the_go_reference() {
        let expected = [
            "7a797800ef6f000000000000040000000864000004044646010000000000",
            "7a797800f673000000010000040000000864000004044646010000000000",
            "7a79780030a2000000020000006400000864000004044646010000000000",
        ];
        let buf = golden_buffer();
        assert_eq!(chunk_count(buf.len()), 3);
        for (pid, want) in expected.iter().enumerate() {
            let h = header(
                chunk_at(&buf, pid as u32),
                pid as u32,
                buf.len() as u32,
                ImageType::Ras,
            );
            assert_eq!(&hex(&h), want, "pid {pid}");
        }
    }

    #[test]
    fn checksum_matches_reference_folding() {
        assert_eq!(checksum(&[]), 0);
        assert_eq!(checksum(&[0xFF; 2]), 0x1FE);
        // 1024·255 = 261120 = 0x3FC00 → fold: 0x3 + 0xFC00 = 0xFC03
        assert_eq!(checksum(&[0xFF; CHUNK_SIZE]), 0xFC03);
    }

    #[test]
    fn chunk_count_and_last_chunk() {
        assert_eq!(chunk_count(1), 1);
        assert_eq!(chunk_count(CHUNK_SIZE), 1);
        assert_eq!(chunk_count(CHUNK_SIZE + 1), 2);
        let buf = golden_buffer();
        assert_eq!(chunk_at(&buf, 2).len(), 100);
    }

    #[test]
    fn image_type_roundtrip() {
        for t in [
            ImageType::Bootbase,
            ImageType::Rom,
            ImageType::Ras,
            ImageType::Romd,
            ImageType::Backup,
        ] {
            assert_eq!(t.to_string().parse::<ImageType>().unwrap(), t);
        }
        assert!("nope".parse::<ImageType>().is_err());
    }
}
